import json
import base64
from fastapi import FastAPI, Form, HTTPException

app = FastAPI()

@app.post("/restore-session")
def restore_session(payload: str = Form(...)):
    try:
        # pickle 대신 JSON을 사용하여 임의 코드 실행 취약점(Insecure Deserialization) 방지
        raw = base64.b64decode(payload)
        session = json.loads(raw)
        if not isinstance(session, dict):
            raise ValueError("세션 데이터는 딕셔너리 형식이어야 합니다.")
    except (ValueError, json.JSONDecodeError) as e:
        raise HTTPException(status_code=400, detail=f"유효하지 않은 세션 데이터입니다: {e}")
    return {"user": session.get("user")}
```

한줄 요약: `pickle`은 역직렬화 시 임의 코드를 실행할 수 있으므로, 안전한 데이터 포맷인 `json`으로 교체하여 Insecure Deserialization 취약점을 제거했습니다.
